CREATE TABLE `fatturazione` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `codice` varchar(255) NOT NULL,
  `dataEmissione` date NOT NULL,
  `importo` double NOT NULL,
  `dataScadenza` date NOT NULL,
  `tipologia` varchar(255) NOT NULL,
  `id_domicilio` bigint NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `codice` (`codice`),
  KEY `fk_fatturazione_domicilio` (`id_domicilio`),
  CONSTRAINT `fk_fatturazione_domicilio` FOREIGN KEY (`id_domicilio`) REFERENCES `domicilio` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=131071 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
